class Solution:
    def divisorSubstrings(self, num: int, k: int) -> int:
        s = str(num)
        ans = 0
        for i in range(len(s) - k + 1):
            v = int(s[i:i + k])
            if v and num % v == 0:
                ans += 1
        return ans

