class Solution:
    def divisorSubstrings(self, num: int, k: int) -> int:
        digits = []
        x = num
        while x:
            digits.append(x % 10)
            x //= 10
        digits.reverse()
        mod = 10 ** (k - 1)
        cur = 0
        for i in range(k):
            cur = cur * 10 + digits[i]
        ans = 0
        i = k - 1
        while True:
            if cur and num % cur == 0:
                ans += 1
            i += 1
            if i == len(digits):
                break
            cur = (cur % mod) * 10 + digits[i]
        return ans

