class Solution {
public:
    int divisorSubstrings(int num, int k) {
        vector<int> d;
        for (int x = num; x; x /= 10) d.push_back(x % 10);
        reverse(d.begin(), d.end());
        long long pw = 1;
        for (int i = 1; i < k; i++) pw *= 10;
        long long cur = 0;
        for (int i = 0; i < k; i++) cur = cur * 10 + d[i];
        int ans = 0;
        for (size_t i = k - 1;; i++) {
            if (cur != 0 && num % cur == 0) ans++;
            if (i + 1 == d.size()) break;
            cur = (cur % pw) * 10 + d[i + 1];
        }
        return ans;
    }
};

