class Solution {
    public int divisorSubstrings(int num, int k) {
        List<Integer> d = new ArrayList<>();
        for (int x = num; x > 0; x /= 10) d.add(x % 10);
        Collections.reverse(d);
        long pw = 1;
        for (int i = 1; i < k; i++) pw *= 10;
        long cur = 0;
        for (int i = 0; i < k; i++) cur = cur * 10 + d.get(i);
        int ans = 0;
        int i = k - 1;
        while (true) {
            if (cur != 0 && num % cur == 0) ans++;
            i++;
            if (i == d.size()) break;
            cur = (cur % pw) * 10 + d.get(i);
        }
        return ans;
    }
}

