var divisorSubstrings = function(num, k) {
    const d = [];
    for (let x = num; x > 0; x = Math.floor(x / 10)) d.push(x % 10);
    d.reverse();
    let pw = 1;
    for (let i = 1; i < k; i++) pw *= 10;
    let cur = 0;
    for (let i = 0; i < k; i++) cur = cur * 10 + d[i];
    let ans = 0, i = k - 1;
